// n8n 2.x: Code node isolado (task runner) - JS puro, sem env vars nem require. Date/JSON ok.
// Reconciliacao BIDIRECIONAL por protocolo entre Splitters (massiva_history) e Voalle (Elleven).
// Regra: quem teve a ULTIMA ACAO e a fonte da verdade. Só propagamos FECHAMENTO; nunca reabrimos.
// Se o lado ABERTO teve acao mais recente que o fechamento do outro -> acao='revisar_manual'.

function unwrap(resp) {
  if (Array.isArray(resp)) return resp;
  if (resp && Array.isArray(resp.data)) return resp.data;
  return [];
}
function ts(v) {
  if (!v) return null;
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d.getTime();
}

const elleven = unwrap($('GET Elleven').first().json);
const hist = unwrap($('GET History (Splitters)').first().json);
const limit = Number($('Config').item.json.limit) || 0;

const ellevenByProto = new Map();
for (const e of elleven) {
  if (e && e.protocolo != null) ellevenByProto.set(String(e.protocolo), e);
}

const itens = [];
for (const h of hist) {
  if (!h || h.protocolo == null) continue;
  const proto = String(h.protocolo);
  const e = ellevenByProto.get(proto);
  if (!e) continue; // so reconcilia o que existe nos dois lados

  const splittersClosed = h.status === 'encerrada';
  const voalleClosed = !!e.finalizado;
  if (splittersClosed === voalleClosed) continue; // em sincronia

  const tSplitters = ts(h.ultimaAcaoEm);
  const tVoalle = voalleClosed ? ts(e.finalizado) : ts(e.criacao);

  let acao;
  let motivoRevisao = null;
  if (splittersClosed && !voalleClosed) {
    // Splitters fechou; Voalle aberto.
    if (tSplitters != null && tVoalle != null && tVoalle > tSplitters) {
      acao = 'revisar_manual';
      motivoRevisao = 'Voalle (aberto) teve acao mais recente (' + e.criacao + ') que o fechamento no Splitters (' + h.ultimaAcaoEm + ').';
    } else {
      acao = 'fechar_voalle';
    }
  } else {
    // Voalle fechou; Splitters aberto.
    if (tSplitters != null && tVoalle != null && tSplitters > tVoalle) {
      acao = 'revisar_manual';
      motivoRevisao = 'Splitters (aberto) teve acao mais recente (' + h.ultimaAcaoEm + ') que o fechamento na Voalle (' + e.finalizado + ').';
    } else {
      acao = 'fechar_splitters';
    }
  }

  const assignmentId = h.assignmentId != null ? String(h.assignmentId) : '';
  itens.push({
    json: {
      protocolo: proto,
      assignmentId: assignmentId,
      acao: acao,
      motivoRevisao: motivoRevisao,
      statusSplitters: h.status,
      ultimaAcaoSplitters: h.ultimaAcaoEm,
      finalizadoVoalle: e.finalizado || null,
      bodyVoalle: {
        assignmentId: assignmentId,
        incidentStatusId: '8',
        description: 'Encerramento automatico via reconciliacao n8n. Protocolo ' + proto + ' encerrado no Splitters em ' + (h.ultimaAcaoEm || 'N/D') + ' e ainda aberto no Voalle.',
        progress: '0',
        priority: '35',
        notificationTarget: '0',
        privateReport: 'true'
      },
      bodySplitters: {
        closedBy: 'reconciliacao-n8n',
        closeDescription: 'Encerrado via reconciliacao automatica. Voalle ja estava fechado em ' + (e.finalizado || 'N/D') + '.'
      }
    }
  });
}

return limit > 0 ? itens.slice(0, limit) : itens;

// Roda 1x por item. Usa pairedItem para recuperar o item de origem (Reconciliar),
// independentemente do caminho (DELETE, PATCH ou revisar_manual direto).
const src = $('Reconciliar (diff)').item.json;
const proto = src.protocolo;
const acao = src.acao;

let categoria;
let motivo = '';

if (acao === 'revisar_manual') {
  categoria = 'revisar';
  motivo = src.motivoRevisao || 'Divergencia que requer revisao manual (nunca reabrir automaticamente).';
} else {
  const j = $json;
  if (j && j.error) {
    categoria = 'falha';
    const msg = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error));
    motivo = 'Erro de transporte: ' + msg;
  } else {
    const status = j ? j.statusCode : undefined;
    const body = (j && j.body !== undefined) ? j.body : j;
    const httpOk = (status === undefined) || (status >= 200 && status < 300);
    const logicOk = body && body.success === true;
    if (httpOk && logicOk) {
      categoria = 'ok';
      motivo = acao === 'fechar_voalle' ? 'Fechado na Voalle (Elleven)' : 'Fechado no Splitters (massiva_history)';
    } else {
      categoria = 'falha';
      motivo = 'HTTP ' + (status !== undefined ? status : '?');
      if (body && Array.isArray(body.messages) && body.messages.length) motivo += ' - ' + body.messages.map(m => m.message).join('; ');
      else if (body && body.message) motivo += ' - ' + body.message;
    }
  }
}

return { json: { protocolo: proto, acao: acao, categoria: categoria, motivo: motivo } };

// Agrega os resultados normalizados e monta o e-mail.
const rows = $input.all().map(i => i.json);
const ok = rows.filter(r => r.categoria === 'ok');
const falhas = rows.filter(r => r.categoria === 'falha');
const revisar = rows.filter(r => r.categoria === 'revisar');
const precisaEmail = falhas.length > 0 || revisar.length > 0;

function li(r) { return '<li>Protocolo <b>' + r.protocolo + '</b> [' + r.acao + ']: ' + r.motivo + '</li>'; }

const assunto = '[Reconciliacao Massivas] ' + ok.length + ' ok, ' + falhas.length + ' falha(s), ' + revisar.length + ' p/ revisao';
let corpoHtml = '<p>Reconciliacao bidirecional Splitters x Voalle (Elleven) concluida.</p>'
  + '<p><b>Fechados com sucesso:</b> ' + ok.length + ' &nbsp; <b>Falhas:</b> ' + falhas.length + ' &nbsp; <b>Revisao manual:</b> ' + revisar.length + '</p>';
if (falhas.length) corpoHtml += '<p><b>Falhas ao propagar fechamento:</b></p><ul>' + falhas.map(li).join('') + '</ul>';
if (revisar.length) corpoHtml += '<p><b>Requerem revisao manual (lado aberto com acao mais recente - nao reaberto automaticamente):</b></p><ul>' + revisar.map(li).join('') + '</ul>';
if (ok.length) corpoHtml += '<p>Sucessos: ' + ok.map(r => r.protocolo + ' (' + r.acao + ')').join(', ') + '</p>';

return [{ json: { precisaEmail, okCount: ok.length, falhaCount: falhas.length, revisarCount: revisar.length, ok, falhas, revisar, assunto, corpoHtml } }];
